const defaultSave=():SaveStateV7=>({v:7,xp:0,storage:{metal:0,copper:0,plastic:0},components:{bearing:0,motor:0,hydraulic:0,electronics:0},processed:{briquette:0,cleanCopper:0,granulate:0},cash:STARTING_CASH,installed:['workbench'],machineLevels:{workbench:1},talents:[],equipmentLevels:{tool:1,cart:1},jobs:[],contract:{index:0,completed:0},totalDestroyed:0,lastSeen:Date.now(),midgame:createDefaultMidgame(),packB:createDefaultPackB(),packC:createDefaultPackC(),packD:createDefaultPackD()});
function loadSave():SaveStateV7{
  try{
    const raw=initialSaveRead.raw,value=raw?JSON.parse(raw):null,base=defaultSave();
    if(value?.v===7)return {...base,...value,storage:{...base.storage,...value.storage},components:{...base.components,...value.components},processed:{...base.processed,...value.processed},equipmentLevels:{...base.equipmentLevels,...value.equipmentLevels},contract:{...base.contract,...value.contract},midgame:normalizeMidgame(value.midgame),packB:normalizePackB(value.packB),packC:normalizePackC(value.packC),packD:normalizePackD(value.packD)};
    if(value?.v===6)return {...base,...value,v:7,storage:{...base.storage,...value.storage},components:{...base.components,...value.components},processed:{...base.processed,...value.processed},equipmentLevels:{...base.equipmentLevels,...value.equipmentLevels},contract:{...base.contract,...value.contract},midgame:normalizeMidgame(value.midgame),packB:normalizePackB(value.packB),packC:normalizePackC(value.packC),packD:createDefaultPackD()};
    if(value?.v===5)return {...base,...value,v:7,storage:{...base.storage,...value.storage},components:{...base.components,...value.components},processed:{...base.processed,...value.processed},equipmentLevels:{...base.equipmentLevels,...value.equipmentLevels},contract:{...base.contract,...value.contract},midgame:normalizeMidgame(value.midgame),packB:normalizePackB(value.packB),packC:createDefaultPackC(),packD:createDefaultPackD()};
    if(value?.v===4)return {...base,...value,v:7,storage:{...base.storage,...value.storage},components:{...base.components,...value.components},processed:{...base.processed,...value.processed},equipmentLevels:{...base.equipmentLevels,...value.equipmentLevels},contract:{...base.contract,...value.contract},midgame:normalizeMidgame(value.midgame),packB:createDefaultPackB(),packC:createDefaultPackC(),packD:createDefaultPackD()};
    if(value?.v===3){const components={...base.components,...value.components};return {...base,...value,v:7,storage:{...base.storage,...value.storage},components,processed:{...base.processed,...value.processed},equipmentLevels:{...base.equipmentLevels,...value.equipmentLevels},contract:{...base.contract,...value.contract},midgame:migrateMidgameFromV3(value.totalDestroyed??0,components),packB:createDefaultPackB(),packC:createDefaultPackC(),packD:createDefaultPackD()};}
    if(value?.v===2){const components={...base.components,...value.components};return {...base,...value,v:7,equipmentLevels:{tool:1,cart:1},jobs:[],contract:{index:0,completed:0},components,midgame:migrateMidgameFromV3(value.totalDestroyed??0,components),packB:createDefaultPackB(),packC:createDefaultPackC(),packD:createDefaultPackD()};}
  }catch{}
  return defaultSave();
}
