let xp=loaded.xp,storage:Record<ResourceKind,number>={...loaded.storage},storedComps:Record<ComponentKind,number>={...loaded.components},processed:Processed={...loaded.processed},cash=loaded.cash,totalDestroyed=loaded.totalDestroyed;
