function applyPackCInventory(inv:PackCInventory){cash=inv.cash;storage.metal=inv.metal;processed.cleanCopper=inv.cleanCopper;packB.materials.steelBlank=inv.steelBlank;packB.modules.structural=inv.structural;packB.modules.control=inv.control;storedComps.hydraulic=inv.hydraulic;midgame.midComponents.pump=inv.pump}
const currentPackDInventory=():PackDInventory=>({cash,metal:storage.metal,cleanCopper:processed.cleanCopper,steelBlank:packB.materials.steelBlank,alloyBillet:packC.materials.alloyBillet,drive:packB.modules.drive,control:packB.modules.control,hydraulicPower:packC.modules.hydraulicPower,heavyFrame:packC.modules.heavyFrame,gearbox:packB.industrial.gearbox,generator:packB.industrial.generator,industrialController:packC.industrial.industrialController,heavyHydraulicCylinder:packC.industrial.heavyHydraulicCylinder});
function applyPackDInventory(inv:PackDInventory){cash=inv.cash;storage.metal=inv.metal;processed.cleanCopper=inv.cleanCopper;packB.materials.steelBlank=inv.steelBlank;packC.materials.alloyBillet=inv.alloyBillet;packB.modules.drive=inv.drive;packB.modules.control=inv.control;packC.modules.hydraulicPower=inv.hydraulicPower;packC.modules.heavyFrame=inv.heavyFrame;packB.industrial.gearbox=inv.gearbox;packB.industrial.generator=inv.generator;packC.industrial.industrialController=inv.industrialController;packC.industrial.heavyHydraulicCylinder=inv.heavyHydraulicCylinder}
