function frame(now:number){const dt=Math.min(.033,Math.max(.001,(now-last)/1000));last=now;diagnostics.frame(dt*1000);if(!platformPaused&&mode==='field'&&talentScreen.hidden&&zoneScreen.hidden&&offlineScreen.hidden){move(dt);combat(dt);updateDrops(dt);updateEffects(dt);cam();hud();const r=canvas.getBoundingClientRect();renderField({ctx,width:r.width,height:r.height,camera,player,targets,selected,drops,sparks,texts,decor,zone:fieldZone,vanOwned:midgame.van.owned||packB.truck.owned||packD.recoveryRig.owned,vanLoad:packD.recoveryRig.owned?recoveryRigWeight(packD):packB.truck.owned?truckWeight(packB):vanWeight(midgame.van),vanCapacity:packD.recoveryRig.owned?RECOVERY_RIG_CAPACITY_KG:packB.truck.owned?TRUCK_CAPACITY_KG:VAN_CAPACITY_KG,workerHere:midgame.worker.assignment===fieldZone||packB.secondWorker.assignment===fieldZone||(packC.crew3.role==='scavenger'&&packC.crew3.assignment===fieldZone)||(packD.crew4.role==='scavenger'&&packD.crew4.assignment===fieldZone)})}else updateEffects(dt);requestAnimationFrame(frame)}
